//! Region to LL2 location ID table.
//!
//! @generated by `tools/launch_library_2/region-map/build_region_map.py` — do not edit by hand.
//! Regenerate after LL2 changes its location list, or after editing
//! `tools/launch_library_2/region-map/regions.toml`.
//!
//! Built from 68 locations, filtered to active sites.
//!
//! Active locations LL2 gives no country. These are lunar landing
//! sites rather than launch sites, so they are in no region and
//! cannot appear in the launch list at all:
//!   182  Malapert-A
//!   183  Mons Mouton
//!
//! Sites no named region claims, held by `Other`.
//! Give one its own region in `regions.toml` if it earns one:
//!     3  [??] Sea Launch
//!    20  [??] Air launch to orbit
//!   144  [??] Air launch to Suborbital flight

use crate::models::RegionFilter;

/// Every region, in the order the filter panel cycles through them.
///
/// Ordered by `tools/launch_library_2/region-map/regions.toml`; `All` leads because it is
/// the unfiltered default.
pub const ALL: [RegionFilter; 12] = [
    RegionFilter::All,
    RegionFilter::US,
    RegionFilter::Europe,
    RegionFilter::RussiaKazakhstan,
    RegionFilter::China,
    RegionFilter::India,
    RegionFilter::Japan,
    RegionFilter::Oceania,
    RegionFilter::MiddleEast,
    RegionFilter::Korea,
    RegionFilter::SouthAmerica,
    RegionFilter::Other,
];

