/// Display name for a region, as shown in the filter panel.
pub fn label(region: RegionFilter) -> &'static str {
    match region {
        RegionFilter::All => "All",
        RegionFilter::US => "US",
        RegionFilter::Europe => "Europe",
        RegionFilter::RussiaKazakhstan => "Russia/Kaz.",
        RegionFilter::China => "China",
        RegionFilter::India => "India",
        RegionFilter::Japan => "Japan",
        RegionFilter::Oceania => "Oceania",
        RegionFilter::MiddleEast => "Mid. East",
        RegionFilter::Korea => "Korea",
        RegionFilter::SouthAmerica => "S. America",
        RegionFilter::Other => "Other",
    }
}
